if(is_array($pendingPackage)&&!empty($pendingPackage['path'])){
 $body.='<section class="card"><h2>2. Back up &amp; repair</h2><p>The uploaded package passed validation. The updater validates it again before applying it, creates its normal backup, and verifies the installed files.</p><p><strong>Version:</strong> '.Ui::e((string)($pendingPackage['version']??'')).'<br><strong>SHA-256:</strong> <code style="overflow-wrap:anywhere">'.Ui::e((string)($pendingPackage['sha256']??'')).'</code></p><form method="post" action="'.Ui::e($base.'/admin/updates/apply').'"><input type="hidden" name="_token" value="'.Ui::e($token).'"><input type="hidden" name="source" value="manual"><div class="actions"><button class="primary"'.($inProgress?' disabled':'').'>Back up &amp; repair official files</button></div></form></section>';
